/**
 * Global Firepower (GFP) data scraper
 * Scrapes country detail pages for 60+ military parameters
 * 
 * URL pattern: https://www.globalfirepower.com/country-military-strength-detail.php?country_id={iso2}
 * 
 * Note: GFP uses ISO2 codes in URLs, not ISO3.
 * We map ISO2 → ISO3 using a lookup table.
 */

export interface GFPCountryData {
  iso3: string;
  name: string;
  gfpRank: number;
  gfpScore: number;
  
  // Manpower
  activePersonnel: number;
  reservePersonnel: number;
  fitForService: number; // reaching military age annually
  
  // Air
  totalAircraft: number;
  fighters: number;
  bombers: number;
  transports: number;
  trainers: number;
  specialMission: number;
  helicopters: number;
  attackHelicopters: number;
  
  // Land
  totalTanks: number;
  lightTanks: number;
  afv: number; // armored fighting vehicles
  apc: number; // armored personnel carriers
  imv: number; // infantry mobility vehicles
  artillery: number;
  selfPropelledArtillery: number;
  towedArtillery: number;
  mlrs: number;
  
  // Naval
  totalNavy: number;
  aircraftCarriers: number;
  helicopterCarriers: number;
  destroyers: number;
  frigates: number;
  corvettes: number;
  submarines: number;
  patrolVessels: number;
  mineWarfare: number;
  
  // Logistics (approximate from GFP)
  ports: number;
  airfields: number;
  merchantFleet: number;
  oilProduction: number;  // bbl/day
  oilConsumption: number; // bbl/day
  oilProvenReserves: number; // bbl
  
  // Financial (supplementary — prefer SIPRI/WB)
  defenseBudget: number; // USD
  purchasingPower: number; // PPP
  
  // Geography
  areaKm2: number;
  coastlineKm: number;
  sharedBorders: number; // km
  waterways: number; // km
}

