/**
 * Get GFP data as a Map by ISO3 code
 */
export function getGFPData(): Map<string, GFPCountryData> {
  const map = new Map<string, GFPCountryData>();
  for (const entry of GFP_RANKINGS_2026) {
    map.set(entry.iso3, entry as unknown as GFPCountryData);
  }
  return map;
}
